public class InnerSourceEndpointStandardSourceEndpointProtocolConfigurationFactory(Action<Humidifier.MediaConnect.SourceEndpointTypes.StandardSourceEndpointProtocolConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.MediaConnect.SourceEndpointTypes.StandardSourceEndpointProtocolConfiguration>
{

    internal InnerSourceEndpointSrtCallerStandardSourceEndpointConfigurationFactory SrtCallerFactory { get; set; }

    internal InnerSourceEndpointSrtListenerStandardSourceEndpointConfigurationFactory SrtListenerFactory { get; set; }

    internal InnerSourceEndpointRistStandardSourceEndpointConfigurationFactory RistFactory { get; set; }

    internal InnerSourceEndpointRtpStandardSourceEndpointConfigurationFactory RtpFactory { get; set; }

    protected override Humidifier.MediaConnect.SourceEndpointTypes.StandardSourceEndpointProtocolConfiguration Create()
    {
        var standardSourceEndpointProtocolConfigurationResult = CreateStandardSourceEndpointProtocolConfiguration();
        factoryAction?.Invoke(standardSourceEndpointProtocolConfigurationResult);

        return standardSourceEndpointProtocolConfigurationResult;
    }

    private Humidifier.MediaConnect.SourceEndpointTypes.StandardSourceEndpointProtocolConfiguration CreateStandardSourceEndpointProtocolConfiguration()
    {
        var standardSourceEndpointProtocolConfigurationResult = new Humidifier.MediaConnect.SourceEndpointTypes.StandardSourceEndpointProtocolConfiguration();

        return standardSourceEndpointProtocolConfigurationResult;
    }
    public override void CreateChildren(Humidifier.MediaConnect.SourceEndpointTypes.StandardSourceEndpointProtocolConfiguration result)
    {
        base.CreateChildren(result);

        result.SrtCaller ??= SrtCallerFactory?.Build();
        result.SrtListener ??= SrtListenerFactory?.Build();
        result.Rist ??= RistFactory?.Build();
        result.Rtp ??= RtpFactory?.Build();
    }

} // End Of Class

